"use client"

import { Skeleton } from "@/components/ui/skeleton"

import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import { CompareParticipantsButton } from "../participantComparison/CompareParticipantsButton"
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ResponsiveContainer,
  Tooltip as RechartsTooltip,
  XAxis,
  YAxis,
} from "recharts"
import { Clock, Eye, Hash, Target } from "lucide-react"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { cn } from "@/lib/utils"
import { KpiCard } from "@/features/analytics/components/KpiCard"
import { apiFetchBlob } from "@/lib/api/apiFetch"
import { getStimulusImageUrl } from "@/features/projects/api/stimulusUrls"
import {
  useAoiMetrics,
  useDistanceTimeseries,
  useFixationData,
  useGazeTimeseries,
  usePupilTimeseries,
} from "../hooks/useAnalyticsData"
import type { AoiMetricItem, FixationDurationMs } from "../types"
import {
  aoiFindings,
  buildAoiSequence,
  countAoiVisits,
  deriveKeyEvents,
  discoveryOrder,
  scenarioEndS,
  scenarioOnsetS,
  summarizeTransitions,
  type AoiLocator,
} from "../aoiInsights"
import {
  AoiLegend,
  AoiOverlay,
  findAoiAtPoint,
  getContainedImageBox,
  type ContainedImageBox,
} from "./AoiOverlay"
import { AnalyticsChartShell } from "./AnalyticsChartShell"
import { AoiFindingsCard } from "./aoi/AoiFindingsCard"
import { AoiMetricsCard } from "./aoi/AoiMetricsCard"
import { AoiSequenceCard } from "./aoi/AoiSequenceCard"
import { AoiSignalPeaksCard } from "./aoi/AoiSignalPeaksCard"
import { AoiTransitionsCard } from "./aoi/AoiTransitionsCard"

interface AoiComparisonTabProps {
  projectId: string
  participantCode: string | null
  scenario: string
  minFixationDurationMs: FixationDurationMs
}

/** Transitions and peaks share a row only while the matrix fits half the width. */
const sideBySideClass = (fixatedAoiCount: number) => (
  fixatedAoiCount <= 3 ? "xl:grid-cols-2" : fixatedAoiCount <= 4 ? "2xl:grid-cols-2" : undefined
)

const formatMs = (value: number | null | undefined) => (
  value == null ? "-" : `${Math.round(value)} ms`
)

const formatPercent = (value: number | null | undefined) => (
  value == null ? "-" : `${value.toFixed(1)}%`
)

function AoiTooltip({
  active,
  payload,
  label,
}: {
  active?: boolean
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  payload?: any[]
  label?: string
}) {
  if (!active || !payload?.length) return null
  const item = payload[0]?.payload as AoiMetricItem | undefined
  if (!item) return null

  return (
    <div className="rounded-lg bg-gray-900 px-3 py-2 text-xs text-white shadow-lg">
      <p className="mb-2 font-semibold">{label}</p>
      <p>Tiempo observado: {formatPercent(item.total_dwell_time_percent)}</p>
      <p>Fijaciones: {item.fixation_count}</p>
      <p>Dwell time: {formatMs(item.total_dwell_time_ms)}</p>
    </div>
  )
}

export function AoiComparisonTab({
  projectId,
  participantCode,
  scenario,
  minFixationDurationMs,
}: AoiComparisonTabProps) {
  const [scenarioImageUrl, setScenarioImageUrl] = useState<string | null>(null)
  const [letterbox, setLetterbox] = useState<ContainedImageBox | null>(null)
  const imageContainerRef = useRef<HTMLDivElement>(null)
  const imageRef = useRef<HTMLImageElement>(null)

  const { data, loading, error } = useAoiMetrics(
    projectId,
    participantCode,
    scenario,
    minFixationDurationMs
  )
  // Same detector and threshold as the AOI metrics, so the sequence built
  // from these fixations agrees with the counts and transitions above it.
  const {
    data: fixationData,
    loading: fixationsLoading,
    error: fixationsError,
  } = useFixationData(projectId, participantCode, scenario, minFixationDurationMs)
  const { data: pupilSeries } = usePupilTimeseries(projectId, participantCode, scenario)
  const { data: gazeSeries } = useGazeTimeseries(projectId, participantCode, scenario)
  const { data: distanceSeries } = useDistanceTimeseries(projectId, participantCode, scenario)

  const computeLetterbox = useCallback(() => {
    setLetterbox(getContainedImageBox(imageRef.current, imageContainerRef.current))
  }, [])

  useEffect(() => {
    let cancelled = false
    let currentUrl: string | null = null

    const load = async () => {
      if (!data?.scenario_file_id) {
        setScenarioImageUrl(null)
        return
      }

      try {
        const blob = await apiFetchBlob(getStimulusImageUrl(projectId, data.scenario_file_id))
        if (cancelled) return
        currentUrl = URL.createObjectURL(blob)
        setScenarioImageUrl(currentUrl)
      } catch {
        if (!cancelled) setScenarioImageUrl(null)
      }
    }

    void load()

    return () => {
      cancelled = true
      if (currentUrl) URL.revokeObjectURL(currentUrl)
    }
  }, [projectId, data?.scenario_file_id])

  useEffect(() => {
    const frame = requestAnimationFrame(() => computeLetterbox())
    const container = imageContainerRef.current
    if (!container || typeof ResizeObserver === "undefined") {
      return () => cancelAnimationFrame(frame)
    }
    const observer = new ResizeObserver(() => computeLetterbox())
    observer.observe(container)
    return () => {
      cancelAnimationFrame(frame)
      observer.disconnect()
    }
  }, [computeLetterbox, scenarioImageUrl])

  const aois = useMemo(() => data?.aois ?? [], [data])

  const topAoi = useMemo(() => {
    if (!aois.length) return null
    return aois.reduce((best, item) => (
      item.total_dwell_time_percent > best.total_dwell_time_percent ? item : best
    ))
  }, [aois])

  const locate = useCallback<AoiLocator>((x, y) => findAoiAtPoint(aois, x, y), [aois])

  const seriesTimes = useMemo(
    () => [pupilSeries?.time, gazeSeries?.time, distanceSeries?.time],
    [distanceSeries, gazeSeries, pupilSeries]
  )
  const onsetS = useMemo(() => scenarioOnsetS(seriesTimes), [seriesTimes])
  const endS = useMemo(
    () => scenarioEndS(seriesTimes, fixationData?.fixations ?? []),
    [fixationData, seriesTimes]
  )

  const sequence = useMemo(
    () => (fixationData && aois.length > 0 ? buildAoiSequence(fixationData.fixations, locate) : null),
    [aois.length, fixationData, locate]
  )
  const visits = useMemo(() => (sequence ? countAoiVisits(sequence) : null), [sequence])
  const discovery = useMemo(() => discoveryOrder(aois, onsetS), [aois, onsetS])
  const ranks = useMemo(
    () => new Map(discovery.seen.map((item) => [item.aoi.id, item.rank])),
    [discovery]
  )
  const transitions = useMemo(
    () => summarizeTransitions(data?.transitions ?? [], aois),
    [aois, data?.transitions]
  )
  const findings = useMemo(
    () => aoiFindings({ aois, discovery, visits, transitions }),
    [aois, discovery, transitions, visits]
  )

  const backendEvents = data?.events
  const events = useMemo(() => {
    if (backendEvents?.length) return backendEvents
    if (aois.length === 0) return []
    return deriveKeyEvents({ pupil: pupilSeries, gaze: gazeSeries, distance: distanceSeries }, locate)
  }, [aois.length, backendEvents, distanceSeries, gazeSeries, locate, pupilSeries])

  const outside = useMemo(() => {
    const totalMs = data?.total_dwell_time_ms ?? 0
    const observedMs = data?.observed_aoi_dwell_time_ms ?? 0
    return {
      percent: totalMs > 0 ? Math.max(0, 100 - (data?.observed_aoi_dwell_time_percent ?? 0)) : 0,
      seconds: Math.max(0, totalMs - observedMs) / 1000,
      fixations: sequence ? sequence.filter((span) => span.aoi == null).length : null,
    }
  }, [data, sequence])

  const fixatedAoiCount = aois.filter((aoi) => aoi.fixation_count > 0).length

  if (scenario === "all") {
    return (
      <div className="analytics-stack">
        <Card>
          <CardHeader>
            <CardTitle>Comparativa AOIs</CardTitle>
            <CardDescription>
              Selecciona un escenario específico para analizar sus áreas de interés.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="flex h-64 items-center justify-center rounded-xl border border-dashed border-border bg-muted/30 text-sm text-muted-foreground">
              Selecciona un escenario para visualizar la comparativa.
            </div>
          </CardContent>
        </Card>
      </div>
    )
  }

  if (!participantCode) {
    return (
      <div className="flex h-64 items-center justify-center rounded-lg border border-dashed border-border bg-muted/30">
        <p className="text-sm text-muted-foreground">Selecciona un participante para ver AOIs.</p>
      </div>
    )
  }

  if (loading) {
    return (
      <div className="analytics-stack">
        <Skeleton className="analytics-state-frame animate-pulse rounded-lg bg-muted" />
        <Skeleton className="analytics-state-frame-compact animate-pulse rounded-lg bg-muted" />
        <Skeleton className="h-64 animate-pulse rounded-lg bg-muted" />
      </div>
    )
  }

  if (error) {
    return (
      <div className="flex h-64 items-center justify-center rounded-lg border border-dashed border-red-200 bg-red-50/50 dark:border-red-900/50 dark:bg-red-900/10">
        <p className="text-sm text-red-500">{error}</p>
      </div>
    )
  }

  if (!data || data.aois.length === 0) {
    return (
      <div className="flex h-64 items-center justify-center rounded-lg border border-dashed border-border bg-muted/30">
        <p className="text-sm text-muted-foreground">
          No hay AOIs definidas para este escenario.
        </p>
      </div>
    )
  }

  return (
    <div className="analytics-stack">
      <div className="analytics-kpi-grid analytics-kpi-grid-four">
        <KpiCard
          label="AOIs"
          value={data.aois.length}
          unit=""
          description="Áreas analizadas"
          Icon={Target}
          bgClass="bg-card"
          iconBgClass="bg-blue-100 dark:bg-blue-900/30"
          iconColorClass="text-blue-500"
          labelColorClass="text-blue-600 dark:text-blue-400"
          decimals={0}
        />
        <KpiCard
          label="Fijaciones"
          value={data.total_fixations}
          unit=""
          description="Total en el escenario"
          Icon={Hash}
          bgClass="bg-card"
          iconBgClass="bg-emerald-100 dark:bg-emerald-900/30"
          iconColorClass="text-emerald-500"
          labelColorClass="text-emerald-600 dark:text-emerald-400"
          decimals={0}
        />
        <KpiCard
          label="Tiempo en AOIs"
          value={data.observed_aoi_dwell_time_percent}
          unit="%"
          description="Dwell time cubierto"
          Icon={Clock}
          bgClass="bg-card"
          iconBgClass="bg-amber-100 dark:bg-amber-900/30"
          iconColorClass="text-amber-500"
          labelColorClass="text-amber-600 dark:text-amber-400"
          decimals={1}
        />
        <KpiCard
          label="Más observada"
          value={topAoi?.total_dwell_time_percent ?? 0}
          unit="%"
          description={topAoi?.name ?? "Sin datos"}
          Icon={Eye}
          bgClass="bg-card"
          iconBgClass="bg-rose-100 dark:bg-rose-900/30"
          iconColorClass="text-rose-500"
          labelColorClass="text-rose-600 dark:text-rose-400"
          decimals={1}
        />
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Comparativa AOIs</CardTitle>
          <CardDescription>
            Fijaciones y concentración visual sobre las áreas definidas del escenario.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_220px] 2xl:gap-6">
            <div className="relative overflow-hidden rounded-lg bg-muted" ref={imageContainerRef}>
              {!scenarioImageUrl ? (
                <Skeleton className="analytics-state-frame w-full animate-pulse bg-muted" />
              ) : (
                <img
                  ref={imageRef}
                  src={scenarioImageUrl}
                  alt={data.scenario}
                  className="analytics-visual-image"
                  onLoad={computeLetterbox}
                />
              )}

              <AoiOverlay aois={data.aois} box={letterbox} />
            </div>

            <div className="self-start pt-2">
              <AoiLegend aois={data.aois} className="flex-col items-start" />
            </div>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="flex flex-row flex-wrap items-start justify-between gap-4">
          <div className="min-w-0 flex-1 basis-72">
            <CardTitle>Distribución temporal por áreas de interés (AOI)</CardTitle>
            <CardDescription>
              Porcentaje del tiempo total de observación dedicado a cada zona del estímulo.
            </CardDescription>
          </div>
          <CompareParticipantsButton
            spec={() => ({
              kind: "aoi",
              title: "Distribución temporal por áreas de interés (AOI)",
              scenario,
              sourceParticipant: participantCode,
              origin: "individual",
              params: { minFixationDurationMs },
            })}
          />
        </CardHeader>
        <CardContent>
          <AnalyticsChartShell xAxisLabel="AOI" variant="compact">
            <ResponsiveContainer className="analytics-chart-plot-frame" width="100%" height="100%">
              <BarChart data={data.aois} margin={{ top: 16, right: 24, left: 0, bottom: 12 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E5E7EB" />
                <XAxis dataKey="name" height={36} tick={{ fontSize: 12 }} tickMargin={8} />
                <YAxis
                  domain={[0, 100]}
                  tick={{ fontSize: 12 }}
                  label={{
                    value: "Tiempo en AOI (%)",
                    angle: -90,
                    position: "insideLeft",
                    style: { textAnchor: "middle" },
                  }}
                />
                <RechartsTooltip content={<AoiTooltip />} cursor={{ fill: "rgba(0, 0, 0, 0.04)" }} />
                <Bar dataKey="total_dwell_time_percent" radius={[4, 4, 0, 0]}>
                  {data.aois.map((aoi) => (
                    <Cell key={aoi.id} fill={aoi.color} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </AnalyticsChartShell>
        </CardContent>
      </Card>

      {/* From here on: conclusions first, then when, how much, and how the gaze moved. */}
      <AoiFindingsCard findings={findings} />

      <AoiSequenceCard
        discovery={discovery}
        sequence={sequence}
        visits={visits}
        loading={fixationsLoading}
        error={fixationsError}
        onsetS={onsetS}
        endS={endS}
        events={events}
      />

      <AoiMetricsCard
        aois={data.aois}
        ranks={ranks}
        onsetS={onsetS}
        visits={visits}
        outside={outside}
        totalFixations={data.total_fixations}
      />

      <div className={cn("grid gap-4", sideBySideClass(fixatedAoiCount))}>
        <AoiTransitionsCard aois={data.aois} summary={transitions} />
        <AoiSignalPeaksCard events={events} onsetS={onsetS} />
      </div>
    </div>
  )
}

"use client"

import { Skeleton } from "@/components/ui/skeleton"
import { Button } from "@/components/ui/button"

import { useCallback, useEffect, useRef, useState } from "react"
import { CompareParticipantsButton } from "../participantComparison/CompareParticipantsButton"
import { Clock, Flame, Hash, Timer } from "lucide-react"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { KpiCard } from "@/features/analytics/components/KpiCard"
import { apiFetchBlob } from "@/lib/api/apiFetch"
import { getStimulusImageUrl } from "@/features/projects/api/stimulusUrls"
import {
  useAoiMetrics,
  useFixationData,
  useHeatmapOverlay,
} from "../hooks/useAnalyticsData"
import type { FixationDurationMs } from "../types"
import {
  AoiLegend,
  AoiOverlay,
  AoiToggleButton,
  containedImageBoxStyle,
  getContainedImageBox,
  type ContainedImageBox,
} from "./AoiOverlay"

interface HeatmapTabProps {
  projectId: string
  participantCode: string | null
  scenario: string
  minFixationDurationMs: FixationDurationMs
}

export function HeatmapTab({
  projectId,
  participantCode,
  scenario,
  minFixationDurationMs,
}: HeatmapTabProps) {
  const [scenarioImageUrl, setScenarioImageUrl] = useState<string | null>(null)
  const [showPurple, setShowPurple] = useState(false)
  const [showAois, setShowAois] = useState(true)
  const [letterbox, setLetterbox] = useState<ContainedImageBox | null>(null)
  const imageContainerRef = useRef<HTMLDivElement>(null)
  const imageRef = useRef<HTMLImageElement>(null)

  // Fixation stats (for KPI cards)
  const { data: fixData, loading: fixLoading } = useFixationData(
    projectId,
    participantCode,
    scenario,
    minFixationDurationMs
  )
  const transformToken =
    fixData?.coordinate_transform?.contract_fingerprint ??
    fixData?.coordinate_transform?.status ??
    "screen-stimulus-v1"
  // null means "not resolved yet", which gates the overlay request. A loaded
  // response missing the field is an older backend, not an unresolved one, so it
  // falls back to 0 rather than blocking the heatmap forever.
  const cacheGeneration = fixData ? (fixData.cache_generation ?? 0) : null

  // PNG heatmap overlay from backend
  const {
    overlayUrl,
    loading: heatmapLoading,
    error: heatmapError,
  } = useHeatmapOverlay(
    projectId,
    participantCode,
    scenario,
    transformToken,
    cacheGeneration,
    minFixationDurationMs
  )
  const {
    data: aoiData,
    loading: aoiLoading,
  } = useAoiMetrics(projectId, participantCode, scenario, minFixationDurationMs)

  const loading = fixLoading || heatmapLoading
  const aois = aoiData?.aois ?? []

  const computeLetterbox = useCallback(() => {
    setLetterbox(
      getContainedImageBox(imageRef.current, imageContainerRef.current)
    )
  }, [])

  // Load scenario background image
  useEffect(() => {
    const fileId = fixData?.scenario_file_id

    let cancelled = false
    let currentUrl: string | null = null

    Promise.resolve().then(() => {
      if (!cancelled) setScenarioImageUrl(null)
    })

    if (!fileId) {
      return () => {
        cancelled = true
      }
    }

    apiFetchBlob(getStimulusImageUrl(projectId, fileId))
      .then((blob) => {
        if (cancelled) return
        currentUrl = URL.createObjectURL(blob)
        setScenarioImageUrl(currentUrl)
      })
      .catch(() => {
        if (!cancelled) setScenarioImageUrl(null)
      })

    return () => {
      cancelled = true
      if (currentUrl) URL.revokeObjectURL(currentUrl)
    }
  }, [projectId, fixData?.scenario_file_id])

  useEffect(() => {
    const frame = requestAnimationFrame(() => computeLetterbox())
    const container = imageContainerRef.current
    if (!container || typeof ResizeObserver === "undefined") {
      return () => cancelAnimationFrame(frame)
    }
    const observer = new ResizeObserver(() => computeLetterbox())
    observer.observe(container)
    return () => {
      cancelAnimationFrame(frame)
      observer.disconnect()
    }
  }, [computeLetterbox, scenarioImageUrl])

  if (scenario === "all") {
    return (
      <div className="analytics-stack">
        <Card>
          <CardHeader>
            <CardTitle>Mapa de calor</CardTitle>
            <CardDescription>
              Representación visual de la densidad de atención sobre el estímulo
              basada en la duración y frecuencia de las fijaciones.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="flex h-64 flex-col items-center justify-center gap-2 rounded-xl border border-dashed border-border bg-muted/30 text-sm text-muted-foreground">
              <Flame className="h-8 w-8 text-muted-foreground/40" />
              <span>
                Selecciona un escenario específico para visualizar el mapa de
                calor
              </span>
            </div>
          </CardContent>
        </Card>
      </div>
    )
  }

  return (
    <div className="analytics-stack">
      <Card>
        <CardHeader className="flex flex-row flex-wrap items-start justify-between gap-4">
          <div className="min-w-0 flex-1 basis-72">
            <CardTitle>Mapa de calor</CardTitle>
            <CardDescription>
              Representación visual de la densidad de atención sobre el estímulo
              basada en la duración y frecuencia de las fijaciones.
            </CardDescription>
          </div>
          <CompareParticipantsButton
            spec={() => ({
              kind: "heatmap",
              title: "Mapa de calor",
              scenario,
              sourceParticipant: participantCode,
              origin: "individual",
              params: { minFixationDurationMs, showAois },
            })}
          />
        </CardHeader>
        <CardContent>
          {!participantCode ? (
            <div className="flex h-64 items-center justify-center text-sm text-muted-foreground">
              Selecciona un participante para ver el mapa de calor.
            </div>
          ) : (
            <>
              {/* KPI Cards */}
              <div className="analytics-kpi-grid">
                <KpiCard
                  label="Fijaciones"
                  value={fixData?.stats?.n_fixations}
                  unit=""
                  description="Total de fijaciones en el escenario"
                  tooltip="Número total de puntos de fijación detectados"
                  Icon={Hash}
                  loading={fixLoading}
                  bgClass="bg-card"
                  iconBgClass="bg-orange-100 dark:bg-orange-900/30"
                  iconColorClass="text-orange-500"
                  labelColorClass="text-orange-600 dark:text-orange-400"
                  decimals={0}
                />
                <KpiCard
                  label="Fijación más larga"
                  value={fixData ? fixData.stats.max_duration_s * 1000 : null}
                  unit="ms"
                  description="Duración de la fijación más prolongada"
                  tooltip="Duración en milisegundos de la fijación más larga"
                  Icon={Timer}
                  loading={fixLoading}
                  bgClass="bg-card"
                  iconBgClass="bg-rose-100 dark:bg-rose-900/30"
                  iconColorClass="text-rose-500"
                  labelColorClass="text-rose-600 dark:text-rose-400"
                  decimals={0}
                />
                <KpiCard
                  label="Duración media"
                  value={fixData ? fixData.stats.avg_duration_s * 1000 : null}
                  unit="ms"
                  description="Promedio de duración por fijación"
                  tooltip="Duración media de cada punto de fijación"
                  Icon={Clock}
                  loading={fixLoading}
                  bgClass="bg-card"
                  iconBgClass="bg-amber-100 dark:bg-amber-900/30"
                  iconColorClass="text-amber-500"
                  labelColorClass="text-amber-600 dark:text-amber-400"
                  decimals={0}
                />
              </div>

              {/* Image + overlay area */}
              {loading ? (
                <Skeleton className="analytics-state-frame w-full animate-pulse rounded-lg bg-muted" />
              ) : heatmapError ? (
                <div className="flex h-64 items-center justify-center text-sm text-muted-foreground">
                  Error al cargar el mapa de calor: {heatmapError}
                </div>
              ) : !fixData || fixData.fixations.length === 0 ? (
                <div className="flex h-64 items-center justify-center text-sm text-muted-foreground">
                  No hay datos de fijación para los filtros seleccionados.
                </div>
              ) : !fixData.scenario_file_id ? (
                <div className="flex h-64 items-center justify-center text-sm text-muted-foreground">
                  No se encontró imagen del escenario seleccionado.
                </div>
              ) : (
                <>
                  <div
                    className="relative overflow-hidden rounded-lg"
                    ref={imageContainerRef}
                  >
                    {/* Background scenario image */}
                    {!scenarioImageUrl ? (
                      <Skeleton className="analytics-state-frame w-full animate-pulse rounded-lg bg-muted" />
                    ) : (
                      <img
                        ref={imageRef}
                        src={scenarioImageUrl}
                        alt="Escenario"
                        className="analytics-visual-image"
                        onLoad={computeLetterbox}
                      />
                    )}

                    {/* Heatmap PNG overlay, pinned to the measured stimulus box */}
                    {overlayUrl && scenarioImageUrl && letterbox && (
                      <img
                        src={overlayUrl}
                        alt="Mapa de calor"
                        aria-hidden="true"
                        className="pointer-events-none z-10"
                        style={{
                          ...containedImageBoxStyle(letterbox),
                          opacity: 0.82,
                        }}
                      />
                    )}

                    {/* Optional purple tint overlay */}
                    {showPurple && (
                      <div
                        className="pointer-events-none absolute inset-0"
                        style={{
                          background: "rgba(60, 0, 160, 0.52)",
                          mixBlendMode: "multiply",
                        }}
                      />
                    )}

                    {showAois && <AoiOverlay aois={aois} box={letterbox} />}
                  </div>

                  {/* Controls bar */}
                  <div className="mt-4 flex flex-wrap items-center justify-between gap-4 rounded-xl border border-border bg-muted/30 px-5 py-3">
                    <AoiLegend aois={showAois ? aois : []} />
                    <div className="ml-auto flex items-center gap-3">
                      <AoiToggleButton
                        enabled={showAois}
                        onToggle={() => setShowAois((value) => !value)}
                        disabled={aois.length === 0 || aoiLoading}
                        count={aois.length}
                      />
                      <Button aria-pressed={showPurple} size="sm" variant="selection"
                        type="button"
                        onClick={() => setShowPurple((p) => !p)}
                        className=""
                      >
                        Filtro violeta
                      </Button>
                    </div>
                  </div>
                </>
              )}
            </>
          )}
        </CardContent>
      </Card>

    </div>
  )
}

"use client"
import { Slider } from "@/components/ui/slider"

import { Skeleton } from "@/components/ui/skeleton"
import { Button } from "@/components/ui/button"

import { useCallback, useEffect, useRef, useState } from "react"
import { CompareParticipantsButton } from "../participantComparison/CompareParticipantsButton"
import { Clock, MapPin, Route, Ruler, Timer } from "lucide-react"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { KpiCard } from "@/features/analytics/components/KpiCard"
import { apiFetchBlob } from "@/lib/api/apiFetch"
import { getStimulusImageUrl } from "@/features/projects/api/stimulusUrls"
import { useAoiMetrics, useScanpathData } from "../hooks/useAnalyticsData"
import {
  formatScanpathObjectiveDetails,
  resolveScanpathRadiusCapMs,
  resolveScanpathTotalDurationS,
  scanpathRadiusForDuration,
} from "../scanpathScale"
import {
  ACTIVE_SCANPATH_STYLE,
  SCANPATH_STYLES,
  scanpathGeometry,
  scanpathLabelFontSize,
} from "../scanpathStyle"
import type { FixationDurationMs } from "../types"
import {
  AoiLegend,
  AoiOverlay,
  AoiToggleButton,
  getContainedImageBox,
  type ContainedImageBox,
} from "./AoiOverlay"

// Switch presets in scanpathStyle.ts ("legacy" restores the previous look).
const scanpathStyle = SCANPATH_STYLES[ACTIVE_SCANPATH_STYLE]

interface ScanpathTabProps {
  projectId: string
  participantCode: string | null
  scenario: string
  minFixationDurationMs: FixationDurationMs
}

export function ScanpathTab({
  projectId,
  participantCode,
  scenario,
  minFixationDurationMs,
}: ScanpathTabProps) {
  const [scenarioImageUrl, setScenarioImageUrl] = useState<string | null>(null)
  const [showAois, setShowAois] = useState(true)

  const imageContainerRef = useRef<HTMLDivElement>(null)
  const imageRef = useRef<HTMLImageElement>(null)

  const [letterbox, setLetterbox] = useState<ContainedImageBox | null>(null)
  const [visibleCount, setVisibleCount] = useState<number | null>(null)

  const { data, loading, error } = useScanpathData(
    projectId,
    participantCode,
    scenario,
    minFixationDurationMs
  )
  const { data: aoiData, loading: aoiLoading } = useAoiMetrics(
    projectId,
    participantCode,
    scenario,
    minFixationDurationMs
  )
  const aois = aoiData?.aois ?? []
  const radiusCapMs = resolveScanpathRadiusCapMs(data?.radius_scale)
  const totalDurationS = data
    ? resolveScanpathTotalDurationS(data.total_duration_s, data.objectives)
    : null

  const computeLetterbox = useCallback(() => {
    setLetterbox(getContainedImageBox(imageRef.current, imageContainerRef.current))
  }, [])

  // Image load / revocation
  useEffect(() => {
    let cancelled = false
    let currentUrl: string | null = null

    if (!data?.scenario_file_id) {
      Promise.resolve().then(() => {
        if (!cancelled) setScenarioImageUrl(null)
      })
      return () => {
        cancelled = true
      }
    }

    apiFetchBlob(getStimulusImageUrl(projectId, data.scenario_file_id))
      .then((blob) => {
        if (cancelled) return
        currentUrl = URL.createObjectURL(blob)
        setScenarioImageUrl(currentUrl)
      })
      .catch(() => {
        if (!cancelled) setScenarioImageUrl(null)
      })

    return () => {
      cancelled = true
      if (currentUrl) URL.revokeObjectURL(currentUrl)
    }
  }, [projectId, data?.scenario_file_id])

  // Recalculate on window resize
  useEffect(() => {
    window.addEventListener("resize", computeLetterbox)
    return () => window.removeEventListener("resize", computeLetterbox)
  }, [computeLetterbox])

  // Reset slider to "show all" whenever data changes
  useEffect(() => {
    if (data?.n_objectives) {
      Promise.resolve().then(() => setVisibleCount(data.n_objectives))
    }
  }, [data?.n_objectives])

  if (scenario === "all") {
    return (
      <div className="analytics-stack">
        <Card>
          <CardHeader>
            <CardTitle>Mapa de recorridos</CardTitle>
            <CardDescription>
              Recorrido visual con nodos numerados por orden de fijación. El
              mismo tamaño representa la misma duración entre participantes.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="flex h-64 flex-col items-center justify-center gap-2 rounded-xl border border-dashed border-border bg-muted/30 text-sm text-muted-foreground">
              <MapPin className="h-8 w-8 text-muted-foreground/40" />
              <span>Selecciona un escenario específico para visualizar el mapa de recorridos</span>
            </div>
          </CardContent>
        </Card>
      </div>
    )
  }

  return (
    <div className="analytics-stack">
      <Card>
        <CardHeader className="flex flex-row flex-wrap items-start justify-between gap-4">
          <div className="min-w-0 flex-1 basis-72">
            <CardTitle>Mapa de recorridos</CardTitle>
            <CardDescription>
              Recorrido visual con nodos numerados por orden de fijación. El mismo
              tamaño representa la misma duración entre participantes.
            </CardDescription>
          </div>
          <CompareParticipantsButton
            spec={() => ({
              kind: "scanpath",
              title: "Mapa de recorridos",
              scenario,
              sourceParticipant: participantCode,
              origin: "individual",
              params: { minFixationDurationMs, showAois },
            })}
          />
        </CardHeader>
        <CardContent>
          {!participantCode ? (
            <div className="flex h-64 items-center justify-center text-sm text-muted-foreground">
              Selecciona un participante para ver el mapa de recorridos.
            </div>
          ) : (
            <>
              <div className="analytics-kpi-grid analytics-kpi-grid-four">
                <KpiCard
                  label="Recorridos"
                  value={data?.n_objectives}
                  unit=""
                  description="Puntos de fijación agrupados"
                  tooltip="Número de objetivos visuales detectados agrupando fijaciones cercanas"
                  Icon={Route}
                  loading={loading}
                  bgClass="bg-card"
                  iconBgClass="bg-indigo-100 dark:bg-indigo-900/30"
                  iconColorClass="text-indigo-500"
                  labelColorClass="text-indigo-600 dark:text-indigo-400"
                  decimals={0}
                />
                <KpiCard
                  label="Distancia"
                  value={data?.total_distance_px}
                  unit="px"
                  description="Longitud total del recorrido"
                  tooltip="Distancia total en píxeles entre fijaciones consecutivas asumiendo resolución 1920×1080"
                  Icon={Ruler}
                  loading={loading}
                  bgClass="bg-card"
                  iconBgClass="bg-emerald-100 dark:bg-emerald-900/30"
                  iconColorClass="text-emerald-500"
                  labelColorClass="text-emerald-600 dark:text-emerald-400"
                  decimals={0}
                />
                <KpiCard
                  label="Promedio"
                  value={data ? data.avg_duration_s * 1000 : null}
                  unit="ms"
                  description="Duración media por fijación"
                  tooltip="Duración promedio de cada punto de fijación agrupado"
                  Icon={Clock}
                  loading={loading}
                  bgClass="bg-card"
                  iconBgClass="bg-rose-100 dark:bg-rose-900/30"
                  iconColorClass="text-rose-500"
                  labelColorClass="text-rose-600 dark:text-rose-400"
                  decimals={0}
                />
                <KpiCard
                  label="Tiempo fijado"
                  value={totalDurationS}
                  unit="s"
                  description="Suma de fijaciones válidas"
                  tooltip="Tiempo total de permanencia en fijaciones válidas; excluye sacadas, mirada inválida y tiempo fuera del estímulo"
                  Icon={Timer}
                  loading={loading}
                  bgClass="bg-card"
                  iconBgClass="bg-sky-100 dark:bg-sky-900/30"
                  iconColorClass="text-sky-500"
                  labelColorClass="text-sky-600 dark:text-sky-400"
                  decimals={2}
                />
              </div>

              {loading ? (
                <Skeleton className="analytics-state-frame w-full animate-pulse rounded-lg bg-muted" />
              ) : error ? (
                <div className="flex h-64 items-center justify-center text-sm text-muted-foreground">
                  Error al cargar los datos: {error}
                </div>
              ) : !data || data.objectives.length === 0 ? (
                <div className="flex h-64 items-center justify-center text-sm text-muted-foreground">
                  No hay datos de fijación para los filtros seleccionados.
                </div>
              ) : !data.scenario_file_id ? (
                <div className="flex h-64 items-center justify-center text-sm text-muted-foreground">
                  No se encontró imagen del escenario seleccionado.
                </div>
              ) : (
                (() => {
                  const total = data.objectives.length
                  const shown = visibleCount ?? total
                  const visibleObjectives = data.objectives.slice(0, shown)
                  const geometry = scanpathGeometry(
                    scanpathStyle,
                    letterbox?.renderedW ?? 0,
                    letterbox?.renderedH ?? 0
                  )
                  const radiusFor = (durationS: number) => {
                    return scanpathRadiusForDuration(
                      durationS,
                      geometry.minRadius,
                      geometry.maxRadius,
                      radiusCapMs
                    )
                  }

                  return (
                    <>
                      <div className="relative" ref={imageContainerRef}>
                        {!scenarioImageUrl ? (
                          <Skeleton className="analytics-state-frame w-full animate-pulse rounded-lg bg-muted" />
                        ) : (
                          <img
                            ref={imageRef}
                            src={scenarioImageUrl}
                            alt="Escenario"
                            className="analytics-visual-image"
                            onLoad={computeLetterbox}
                          />
                        )}
                        {showAois && (
                          <AoiOverlay aois={aois} box={letterbox} className="z-10" />
                        )}
                        {letterbox && (
                          <svg
                            className="pointer-events-none absolute inset-0 z-20"
                            width="100%"
                            height="100%"
                            viewBox={`0 0 ${letterbox.cW} ${letterbox.cH}`}
                          >
                            {/* Lines between objectives */}
                            {visibleObjectives.map((obj, i) => {
                              if (i === 0) return null
                              const prev = visibleObjectives[i - 1]
                              return (
                                <line
                                  key={`line-${obj.id}`}
                                  x1={letterbox.offsetX + prev.cx * letterbox.renderedW}
                                  y1={letterbox.offsetY + prev.cy * letterbox.renderedH}
                                  x2={letterbox.offsetX + obj.cx * letterbox.renderedW}
                                  y2={letterbox.offsetY + obj.cy * letterbox.renderedH}
                                  stroke={scanpathStyle.lineStroke}
                                  strokeWidth={geometry.lineWidth}
                                  strokeLinecap="round"
                                />
                              )
                            })}
                            {/* Nodes */}
                            {visibleObjectives.map((obj) => {
                              const cx = letterbox.offsetX + obj.cx * letterbox.renderedW
                              const cy = letterbox.offsetY + obj.cy * letterbox.renderedH
                              const r = radiusFor(obj.duration_s)
                              const fontSize = scanpathLabelFontSize(scanpathStyle, r)
                              const details = formatScanpathObjectiveDetails(obj)
                              return (
                                <g
                                  key={`node-${obj.id}`}
                                  data-testid={`scanpath-fixation-${obj.id}`}
                                  data-duration-ms={Math.round(obj.duration_s * 1_000)}
                                  data-radius={r}
                                  role="img"
                                  tabIndex={0}
                                  aria-label={details}
                                  className="group pointer-events-auto cursor-help focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
                                >
                                  <title>{details}</title>
                                  <circle
                                    cx={cx}
                                    cy={cy}
                                    r={r}
                                    fill={scanpathStyle.nodeFill}
                                    stroke={scanpathStyle.nodeStroke}
                                    strokeWidth={geometry.nodeStrokeWidth}
                                    className={scanpathStyle.nodeClassName}
                                  />
                                  <text
                                    x={cx}
                                    y={cy}
                                    textAnchor="middle"
                                    dominantBaseline="central"
                                    fill={scanpathStyle.labelFill}
                                    fontSize={fontSize}
                                    fontWeight="bold"
                                    style={{
                                      paintOrder: "stroke",
                                      stroke: scanpathStyle.labelHalo,
                                      strokeWidth: scanpathStyle.labelHaloWidth,
                                      strokeLinejoin: scanpathStyle.labelHaloLineJoin,
                                    }}
                                  >
                                    {obj.id}
                                  </text>
                                </g>
                              )
                            })}
                          </svg>
                        )}
                      </div>
                      <div className="mt-4 flex flex-wrap items-center justify-between gap-4 rounded-xl border border-border bg-muted/30 px-5 py-3">
                        <AoiLegend aois={showAois ? aois : []} />
                        <div className="ml-auto flex items-center">
                          <AoiToggleButton
                            enabled={showAois}
                            onToggle={() => setShowAois((value) => !value)}
                            disabled={aois.length === 0 || aoiLoading}
                            count={aois.length}
                          />
                        </div>
                      </div>
                      {/* Playback slider */}
                      {data.objectives.length > 1 && (
                        <div className="mt-4 flex items-center gap-4 rounded-xl border border-border bg-muted/30 px-5 py-3">
                          <span className="shrink-0 text-sm font-medium text-foreground">
                            Fijación {shown} de {total}
                          </span>
                          <Slider
                            aria-label="Fijaciones visibles"
                            min={1}
                            max={total}
                            step={1}
                            value={[shown]}
                            onValueChange={([value]) => setVisibleCount(value)}
                          />
                          {shown < total && (
                            <Button size="sm" variant="outline"
                              type="button"
                              onClick={() => setVisibleCount(total)}
                              className="shrink-0"
                            >
                              Ver todos
                            </Button>
                          )}
                        </div>
                      )}
                    </>
                  )
                })()
              )}
            </>
          )}
        </CardContent>
      </Card>

    </div>
  )
}

